const changes = $input.first().json.changes ?? [];

return changes.map(change => ({
  json: {
    file: change.new_path ?? change.old_path,
    oldFile: change.old_path ?? null,
    newFile: change.new_path ?? null,
    diff: change.diff ?? '',
    deletedFile: change.deleted_file ?? false,
    newFileAdded: change.new_file ?? false,
    renamedFile: change.renamed_file ?? false
  }
}));

