(() => {
  let result;

  try {
    result = JSON.parse($json.output || '{"findings":[]}');
  } catch {
    return '## 🔐 Security Analysis\n\nUnable to parse the analyzer response.';
  }

  const findings = Array.isArray(result.findings) ? result.findings : [];
  const confirmed = findings.filter(f => f.isFalsePositive === false);
  const unconfirmed = findings.filter(f => f.isFalsePositive === true);

  let md = '## 🔐 Security Analysis\n\n';

  if (confirmed.length === 0) {
    md += '### ✅ No confirmed vulnerabilities\n\n';
    md += 'The security analyzer did not confirm any genuine security vulnerabilities in the detected changes.\n';
  } else {
    md += `### 🚨 Confirmed vulnerabilities (${confirmed.length})\n\n`;

    confirmed.forEach((f, i) => {
      md += `#### ${i + 1}. ${f.vulnerabilityType || 'Security vulnerability'}\n\n`;
      md += `- **Severity:** ${f.severity || 'Unknown'}\n`;
      md += `- **File:** \`${f.file || 'Unknown'}\`\n`;
      md += `- **Line:** \`${f.line || 'Unknown'}\`\n\n`;
      md += `**Explanation**\n\n${f.explanation || 'No explanation provided.'}\n\n`;

      if (f.remediation) {
        md += `**Remediation**\n\n${f.remediation}\n\n`;
      }

      md += '---\n\n';
    });
  }

  if (unconfirmed.length > 0) {
    md += `### ℹ️ Unconfirmed findings (${unconfirmed.length})\n\n`;
    md += 'These findings were reviewed but the supplied changes did not provide enough evidence to confirm an exploitable vulnerability.\n\n';

    unconfirmed.forEach((f, i) => {
      md += `**${i + 1}. ${f.vulnerabilityType || 'Security concern'}** — \`${f.severity || 'Low'}\`\n\n`;
      md += `- **File:** \`${f.file || 'Unknown'}\`\n`;
      md += `- **Line:** \`${f.line || 'Unknown'}\`\n`;
      md += `- **Analysis:** ${f.explanation || 'No explanation provided.'}\n\n`;
    });
  }

  return md;
})()
}}

