const items = $input.all();

const findings = [];

for (const item of items) {
  const rawOutput = item.json.output;

  // Ignore empty agent responses
  if (!rawOutput || typeof rawOutput !== 'string') {
    continue;
  }

  let result;

  try {
    result = JSON.parse(rawOutput);
  } catch {
    // Ignore malformed agent responses for now
    continue;
  }

  // Ignore empty/malformed results
  if (!result || !result.file || !Array.isArray(result.findings)) {
    continue;
  }

  for (const finding of result.findings) {
    findings.push({
      file: result.file,
      oldFile: item.json.oldFile ?? null,
      newFile: item.json.newFile ?? null,
      deletedFile: item.json.deletedFile ?? false,
      newFileAdded: item.json.newFileAdded ?? false,
      renamedFile: item.json.renamedFile ?? false,
      line: finding.line ?? null,
      code: finding.code ?? null,
      reason: finding.description ?? null,
      diff: item.json.diff ?? null
    });
  }
}

return [
  {
    json: {
      suspicious: findings.length > 0,
      findings,
      findingCount: findings.length,
      affectedFiles: [...new Set(findings.map(f => f.file))]
    }
  }
];

return { 
  output:'OWASP Checker: No suspicious security patterns were detected in the changes introduced by this merge request.'
};

return $input.all().map(item => {
  const content = item.json.choices?.[0]?.message?.content;

  if (!content || typeof content !== 'string') {
    return {
      json: {
        ...item.json,
        output: ''
      }
    };
  }

  return {
    json: {
      ...item.json,
      output: content
    }
  };
});
